package frontmatter

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// ErrNoDate is returned when a page's front matter has no date field.
var ErrNoDate = errors.New("front matter has no date")

// dateLayouts are the accepted forms of the `date:` field, most specific first.
var dateLayouts = []string{
	time.RFC3339,
	"2006-01-02T15:04:05",
	"2006-01-02",
}

// parseFrontMatterDate turns the raw `date:` value of a page's front matter into a timestamp.
// file is the page's path, used only in the error message.
func parseFrontMatterDate(file, raw string) (time.Time, error) {
	value := strings.Trim(strings.TrimSpace(raw), `"'`)
	if value == "" {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	for _, layout := range dateLayouts {
		parsed, err := time.Parse(layout, value)
		if err == nil {
			return parsed.UTC(), nil
		}
	}

	return time.Time{}, fmt.Errorf("invalid date in %s: %q", file, value)
}

// PageDate reads the date field from parsed front matter.
func PageDate(file string, fields map[string]string) (time.Time, error) {
	raw, ok := fields["date"]
	if !ok {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	return parseFrontMatterDate(file, raw)
}

package frontmatter

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestParseFrontMatterDate(t *testing.T) {
	t.Parallel()

	valid := []struct {
		name string
		raw  string
		want time.Time
	}{
		{"rfc3339 with Z", "2026-03-14T09:30:00Z", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
		{"rfc3339 with offset", "2026-03-14T11:30:00+02:00", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
		{"date only", "2026-03-14", time.Date(2026, 3, 14, 0, 0, 0, 0, time.UTC)},
		{"quoted value", `"2026-03-14T09:30:00Z"`, time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
	}
	for _, tc := range valid {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, err := parseFrontMatterDate("posts/pi-day.md", tc.raw)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !got.Equal(tc.want) || got.Location() != time.UTC {
				t.Fatalf("got %v, want %v in UTC", got, tc.want)
			}
		})
	}

	t.Run("invalid names the file", func(t *testing.T) {
		t.Parallel()
		_, err := parseFrontMatterDate("posts/bad.md", "14 March 2026")
		if err == nil || !strings.Contains(err.Error(), "invalid date in posts/bad.md") {
			t.Fatalf("want an error naming the file, got %v", err)
		}
	})
}

func TestPageDate(t *testing.T) {
	t.Parallel()

	t.Run("missing date", func(t *testing.T) {
		t.Parallel()
		_, err := PageDate("posts/draft.md", map[string]string{"title": "Draft"})
		if !errors.Is(err, ErrNoDate) {
			t.Fatalf("want ErrNoDate, got %v", err)
		}
	})
}

package slug

import (
	"strings"
	"unicode"
)

// asciiFold maps the accented Latin letters that appear in titles to their plain ASCII base.
var asciiFold = map[rune]string{
	'à': "a", 'á': "a", 'â': "a", 'ä': "a", 'ã': "a", 'å': "a",
	'ç': "c",
	'è': "e", 'é': "e", 'ê': "e", 'ë': "e",
	'ì': "i", 'í': "i", 'î': "i", 'ï': "i",
	'ñ': "n",
	'ò': "o", 'ó': "o", 'ô': "o", 'ö': "o", 'õ': "o", 'ø': "o",
	'ù': "u", 'ú': "u", 'û': "u", 'ü': "u",
	'ý': "y", 'ÿ': "y",
	'ß': "ss", 'æ': "ae", 'œ': "oe",
}

// Slugify builds a page's URL slug from its title: lowercase, ASCII-fold, with every run of
// non-alphanumeric characters collapsed to one hyphen and hyphens trimmed from both ends.
func Slugify(title string) string {
	var out strings.Builder
	pendingHyphen := false

	for _, r := range strings.ToLower(title) {
		if folded, ok := asciiFold[r]; ok {
			if pendingHyphen && out.Len() > 0 {
				out.WriteByte('-')
			}
			out.WriteString(folded)
			pendingHyphen = false
			continue
		}
		if r < unicode.MaxASCII && (unicode.IsLetter(r) || unicode.IsDigit(r)) {
			if pendingHyphen && out.Len() > 0 {
				out.WriteByte('-')
			}
			out.WriteRune(r)
			pendingHyphen = false
			continue
		}
		pendingHyphen = true
	}

	return out.String()
}

package slug

import "testing"

func TestSlugify(t *testing.T) {
	t.Parallel()

	cases := []struct {
		name  string
		title string
		want  string
	}{
		{"plain title", "Hello World", "hello-world"},
		{"accents fold to ascii", "Crème Brûlée à la Café", "creme-brulee-a-la-cafe"},
		{"punctuation runs collapse", "Go -- Fast!!! & Safe", "go-fast-safe"},
		{"leading and trailing symbols trimmed", "  ...Why Slugs?!  ", "why-slugs"},
		{"digits kept", "Top 10 Tips for 2026", "top-10-tips-for-2026"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := Slugify(tc.title); got != tc.want {
				t.Fatalf("Slugify(%q) = %q, want %q", tc.title, got, tc.want)
			}
		})
	}
}

package render

import (
	"html/template"
	"os"
	"sync"
	"time"
)

type cacheEntry struct {
	tmpl    *template.Template
	modTime time.Time
}

// TemplateCache holds compiled templates by path and recompiles one when its file changes.
type TemplateCache struct {
	mu      sync.Mutex
	entries map[string]cacheEntry
	stat    func(string) (os.FileInfo, error)
	compile func(string) (*template.Template, error)
}

// NewTemplateCache returns an empty cache that reads templates from disk.
func NewTemplateCache() *TemplateCache {
	return &TemplateCache{
		entries: map[string]cacheEntry{},
		stat:    os.Stat,
		compile: func(path string) (*template.Template, error) { return template.ParseFiles(path) },
	}
}

// Get returns the compiled template for path, dropping and recompiling the cached entry when the
// file's modification time differs from the one it was compiled at.
func (c *TemplateCache) Get(path string) (*template.Template, error) {
	info, err := c.stat(path)
	if err != nil {
		return nil, err
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	if entry, ok := c.entries[path]; ok && entry.modTime.Equal(info.ModTime()) {
		return entry.tmpl, nil
	}

	delete(c.entries, path)

	tmpl, err := c.compile(path)
	if err != nil {
		return nil, err
	}

	c.entries[path] = cacheEntry{tmpl: tmpl, modTime: info.ModTime()}

	return tmpl, nil
}

package render

import (
	"html/template"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func newCountingCache(t *testing.T) (*TemplateCache, *int) {
	t.Helper()
	compiles := 0
	cache := NewTemplateCache()
	inner := cache.compile
	cache.compile = func(path string) (*template.Template, error) {
		compiles++
		return inner(path)
	}
	return cache, &compiles
}

func writeTemplate(t *testing.T, dir, body string) string {
	t.Helper()
	path := filepath.Join(dir, "page.html")
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestTemplateCache(t *testing.T) {
	t.Parallel()

	t.Run("miss compiles", func(t *testing.T) {
		t.Parallel()
		cache, compiles := newCountingCache(t)
		path := writeTemplate(t, t.TempDir(), "<p>{{.}}</p>")
		if _, err := cache.Get(path); err != nil {
			t.Fatal(err)
		}
		if *compiles != 1 {
			t.Fatalf("compiles = %d, want 1", *compiles)
		}
	})

	t.Run("hit same mtime no recompile", func(t *testing.T) {
		t.Parallel()
		cache, compiles := newCountingCache(t)
		path := writeTemplate(t, t.TempDir(), "<p>{{.}}</p>")
		for range 3 {
			if _, err := cache.Get(path); err != nil {
				t.Fatal(err)
			}
		}
		if *compiles != 1 {
			t.Fatalf("compiles = %d, want 1", *compiles)
		}
	})

	t.Run("touched file is recompiled", func(t *testing.T) {
		t.Parallel()
		cache, compiles := newCountingCache(t)
		path := writeTemplate(t, t.TempDir(), "<p>{{.}}</p>")
		if _, err := cache.Get(path); err != nil {
			t.Fatal(err)
		}
		later := time.Now().Add(time.Hour)
		if err := os.Chtimes(path, later, later); err != nil {
			t.Fatal(err)
		}
		if _, err := cache.Get(path); err != nil {
			t.Fatal(err)
		}
		if *compiles != 2 {
			t.Fatalf("compiles = %d, want 2", *compiles)
		}
	})

	t.Run("stat error propagates", func(t *testing.T) {
		t.Parallel()
		cache, _ := newCountingCache(t)
		if _, err := cache.Get(filepath.Join(t.TempDir(), "missing.html")); err == nil {
			t.Fatal("want an error for a missing template")
		}
	})
}
